    assertTrue(not.eval(null, null).asBool());
    expr = new BinaryEval(Type.LEQ, e2, e1);
    assertFalse(expr.eval(null, null).asBool());
    not = new NotEval(expr);
    assertTrue(not.eval(null, null).asBool());
