public final void testCompare() {
    Schema schema = new Schema();
    schema.addColumn("col1", DataType.INT);
    schema.addColumn("col2", DataType.INT);
    schema.addColumn("col3", DataType.INT);
    schema.addColumn("col4", DataType.INT);
